/*
 * Generates tests/lz4_golden.generated.ts: Nalix LZ4 frames built with the reference
 * LZ4 encoder (LZ4_compress_default, vendored in clients/c) using the same header layout
 * as clients/c/src/compression.c:
 *   [OriginalLength u32 LE | CompressedLength u32 LE (total, incl. 8-byte header) | raw LZ4 block]
 *
 * Inputs are generated by simple formulas that the TS test reproduces exactly:
 *   GOLDEN_TEXT_3343   : "The quick brown fox jumps over the lazy dog. " repeated, 3343 bytes
 *   GOLDEN_RANDOM_600  : xorshift32 (seed 0x12345678), low byte of each state, 600 bytes
 *   GOLDEN_MIXED_4096  : 256-byte zero runs alternating with xorshift32 bytes (seed 0x9e3779b9)
 *
 * Build and run from clients/ts (requires a C compiler):
 *   cc -O2 -I ../c/src/third_party/lz4 tests/golden/lz4_golden_gen.c \
 *      ../c/src/third_party/lz4/lz4.c -o /tmp/lz4_golden_gen && \
 *   /tmp/lz4_golden_gen > tests/lz4_golden.generated.ts
 */
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "lz4.h"

static uint32_t g_state;

static uint8_t xorshift_byte(void) {
    g_state ^= g_state << 13;
    g_state ^= g_state >> 17;
    g_state ^= g_state << 5;
    return (uint8_t)(g_state & 0xffu);
}

static void emit_frame(const char* ts_name, const uint8_t* in, int n) {
    int cap = LZ4_compressBound(n);
    char* block = (char*)malloc((size_t)cap);
    int block_len = LZ4_compress_default((const char*)in, block, n, cap);
    if (block_len <= 0) {
        fprintf(stderr, "LZ4_compress_default failed for %s\n", ts_name);
        exit(1);
    }

    uint32_t orig = (uint32_t)n;
    uint32_t total = (uint32_t)block_len + 8u;

    printf("export const %s =\n  '", ts_name);
    for (int i = 0; i < 4; i++) printf("%02x", (orig >> (8 * i)) & 0xffu);
    for (int i = 0; i < 4; i++) printf("%02x", (total >> (8 * i)) & 0xffu);
    for (int i = 0; i < block_len; i++) printf("%02x", (uint8_t)block[i]);
    printf("';\n\n");

    free(block);
}

int main(void) {
    static const char pattern[] = "The quick brown fox jumps over the lazy dog. ";
    const int pattern_len = (int)strlen(pattern);

    printf("// Generated by tests/golden/lz4_golden_gen.c. Do not edit by hand.\n");
    printf("// Reference encoder: LZ4_compress_default (clients/c/src/third_party/lz4).\n\n");

    uint8_t* text = (uint8_t*)malloc(3343);
    for (int i = 0; i < 3343; i++) text[i] = (uint8_t)pattern[i % pattern_len];
    emit_frame("GOLDEN_TEXT_3343", text, 3343);

    g_state = 0x12345678u;
    uint8_t* random600 = (uint8_t*)malloc(600);
    for (int i = 0; i < 600; i++) random600[i] = xorshift_byte();
    emit_frame("GOLDEN_RANDOM_600", random600, 600);

    g_state = 0x9e3779b9u;
    uint8_t* mixed = (uint8_t*)malloc(4096);
    for (int i = 0; i < 4096; i++) mixed[i] = (((i >> 8) & 1) == 0) ? 0 : xorshift_byte();
    emit_frame("GOLDEN_MIXED_4096", mixed, 4096);

    free(text);
    free(random600);
    free(mixed);
    return 0;
}
